{
  "schemaVersion": "0.2",
  "slug": "dialog",
  "name": "Dialog",
  "status": "experimental",
  "purpose": "Presents a blocking task in a modal on large screens and a bottom sheet on compact screens.",
  "scenarios": [
    "Review a setting before continuing",
    "Confirm a destructive action",
    "Collect a short form without leaving the page"
  ],
  "props": {
    "triggerLabel": {
      "type": "string",
      "required": true,
      "description": "Accessible name of the element that opens the dialog."
    },
    "title": {
      "type": "string",
      "required": true,
      "description": "Dialog heading and accessible name."
    },
    "description": {
      "type": "string",
      "required": true,
      "description": "Supporting text associated with the dialog."
    },
    "closeLabel": {
      "type": "string",
      "required": true,
      "description": "Accessible name of the close action."
    },
    "open": {
      "type": "boolean",
      "required": false,
      "description": "Optional controlled open state."
    },
    "defaultOpen": {
      "type": "boolean",
      "required": false,
      "description": "Uncontrolled initial open state."
    },
    "onOpenChange": {
      "type": "event",
      "required": false,
      "description": "Called when the dialog opens or closes. Compact morphs to a sheet; the event is the same.",
      "payload": "(open: boolean) => void"
    },
    "children": {
      "type": "node",
      "required": false,
      "description": "Optional body between the description and the close action."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "closed",
      "description": "Not shown; trigger is in the tab order."
    },
    {
      "name": "open",
      "description": "Shown; focus is trapped until dismiss."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page"
    ],
    "allowedChildren": [
      "text",
      "input",
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not nest dialogs.",
    "Do not trap focus without an Escape or close control."
  ],
  "a11y": {
    "role": "dialog",
    "keyboard": [
      "Enter/Space on trigger opens",
      "Tab cycles inside",
      "Escape closes and restores trigger focus"
    ],
    "focus": "Focus moves into the dialog on open and returns to the trigger on close. Delegated to Ark UI / Zag.",
    "labeling": "Title labels the dialog; description is associated.",
    "wcag": [
      "2.1.1",
      "2.4.3",
      "2.4.7"
    ]
  },
  "responsive": {
    "strategy": "Centered modal on medium/large; compact uses a block-end bottom sheet. Escape dismisses at every breakpoint. Morph is container-driven via the viewport-sized positioner (@container 48rem == tablet).",
    "breakpoints": {
      "compact": "Bottom sheet: content docks to block-end, full inline size, start-edge radii only.",
      "medium": "Centered modal, max inline size 32rem.",
      "large": "Centered modal, max inline size 32rem."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical inset, padding, and action alignment. Close control is not mirrored. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "dialog",
    "states": [
      "open",
      "closed"
    ],
    "intents": [
      "confirm-decision",
      "collect-input"
    ]
  },
  "mechanics": "Dialog is one component. CSS container queries on the positioner restyle it: compact docks as a block-end sheet; from 48rem it is a centered modal. Escape and the close control dismiss at every breakpoint. onOpenChange(open) is the only open-state event — do not swap Dialog for ActionSheet with matchMedia. Focus trap and restore are delegated to Ark/Zag.",
  "usage": [
    "Import Dialog from @chameleon-ui/components.",
    "Pass triggerLabel, title, description, and closeLabel. Bind open and onOpenChange for controlled use.",
    "Put extra fields in children. Do not nest dialogs. Do not emit a second ActionSheet for compact."
  ],
  "exports": [
    {
      "name": "Dialog",
      "kind": "component",
      "signature": "function Dialog(props: DialogProps): JSX.Element",
      "description": "Blocking task: modal on large, sheet on compact. Same events."
    },
    {
      "name": "DialogProps",
      "kind": "type",
      "signature": "interface DialogProps",
      "description": "triggerLabel, title, description, closeLabel, open, onOpenChange, children."
    }
  ]
}

